  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> filter(fn: (r) => exists r.service and r.service != "")
  |> filter(fn: (r) => contains(value: r.service, set: ["telnet", "ftp", "ftp-data", "tftp", "http", "http-alt", "http-proxy", "smtp", "pop3", "imap", "snmp", "netbios", "syslog", "vnc", "ldap", "redis", "memcached"]))
  |> group(columns: ["service", "src_ip", "dst_ip"])
  |> reduce(identity: {flows: 0, bytes: 0}, fn: (r, accumulator) => ({
      flows: accumulator.flows + 1,
      bytes: accumulator.bytes + r._value}))
  |> group()
  |> sort(columns: ["bytes"], desc: true)
  |> limit(n: 30)
  |> keep(columns: ["service", "src_ip", "dst_ip", "flows", "bytes"])

