  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r._field == "dst_port")
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> map(fn: (r) => ({protocol: r.protocol, port: r._value, n: 1}))
  |> group(columns: ["protocol", "port"])
  |> count(column: "n")
  |> group()
  |> map(fn: (r) => ({port: r.port, flows: r.n,
                      proto: if r.protocol == "6" then "TCP"
                             else if r.protocol == "17" then "UDP"
                             else if r.protocol == "1" then "ICMP"
                             else r.protocol}))
  |> sort(columns: ["flows"], desc: true)
  |> limit(n: 30)

